export const BUILTIN_BY_ID: Record<string, CardTemplate> = Object.fromEntries(BUILTIN_TEMPLATES.map((t) => [t.id, t]));
export const DEFAULT_TEMPLATE_ID = 'corp-blue';
export const TEMPLATE_CATEGORIES = ['Corporate', 'Modern', 'Industry', 'Security', 'Custom'];

/** Deep clone so callers can safely mutate a template (designer edits). */
export function cloneTemplate(t: CardTemplate): CardTemplate {
  return JSON.parse(JSON.stringify(t));
}
